/* eslint-disable */
// =====================================================================
// Generación de imágenes PNG de las gráficas diarias (costo, llamadas de
// emergencia y reparaciones por día) para incrustarlas IDÉNTICAS en el PDF y en
// el Excel de los reportes. Se dibujan con @napi-rs/canvas y dos fuentes
// DejaVu Sans embebidas (subconjunto) para no depender de las fuentes del
// sistema ni de archivos externos.
//
// Robustez: si @napi-rs/canvas no está instalado o falla, las funciones
// devuelven null y los reportes usan su representación de respaldo (barras
// vectoriales en el PDF y barras de datos en el Excel). Nunca rompen la
// exportación.
// =====================================================================

// Fuentes DejaVu Sans (subconjunto) en base64. Licencia Bitstream Vera / DejaVu.
const FUENTE_REGULAR_B64 =
  '';
const FUENTE_BOLD_B64 =
  '';

let modulo: any = null;
let intentado = false;
// Carga perezosa y protegida de @napi-rs/canvas + registro de fuentes embebidas.
function obtenerCanvas(): any {
  if (intentado) return modulo;
  intentado = true;
  try {
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const c = require('@napi-rs/canvas');
    try {
      c.GlobalFonts.register(Buffer.from(FUENTE_REGULAR_B64, 'base64'), 'CeibalChart');
      c.GlobalFonts.register(Buffer.from(FUENTE_BOLD_B64, 'base64'), 'CeibalChartBold');
    } catch {
      /* Si el registro falla, se intentará con las fuentes del sistema. */
    }
    modulo = c;
  } catch {
    modulo = null; // La librería no está disponible: se usará el respaldo.
  }
  return modulo;
}

export interface DiaSerie {
  fecha: string;
  dia: number;
  costo: number;
  emergencias: number;
  reparaciones: number;
}

// Calcula marcas "redondas" para el eje Y (0, paso, 2·paso, … máximo).
function marcasEje(max: number, cantidad: number, entero: boolean): number[] {
  if (max <= 0) return [0, 1];
  let base = max / cantidad;
  if (entero) base = Math.max(1, base);
  const mag = Math.pow(10, Math.floor(Math.log10(base)));
  const norm = base / mag;
  let paso =
    mag * (norm <= 1 ? 1 : norm <= 2 ? 2 : norm <= 2.5 ? 2.5 : norm <= 5 ? 5 : 10);
  if (entero) paso = Math.max(1, Math.round(paso));
  const tope = Math.ceil(max / paso) * paso;
  const marcas: number[] = [];
  for (let v = 0; v <= tope + 1e-9; v += paso) {
    marcas.push(entero ? Math.round(v) : Math.round(v * 100) / 100);
  }
  return marcas;
}

// Barra con esquinas superiores redondeadas (como en la web).
function barra(ctx: any, x: number, y: number, w: number, h: number): void {
  const r = Math.min(3, w / 2, h);
  ctx.beginPath();
  ctx.moveTo(x, y + h);
  ctx.lineTo(x, y + r);
  ctx.quadraticCurveTo(x, y, x + r, y);
  ctx.lineTo(x + w - r, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + r);
  ctx.lineTo(x + w, y + h);
  ctx.closePath();
  ctx.fill();
}

// Dibuja UNA gráfica de barras (una serie) y devuelve el PNG.
function graficaBarras(
  c: any,
  o: { datos: DiaSerie[]; campo: string; color: string; titulo: string; ejeY: string; moneda?: boolean },
): Buffer {
  const { datos, campo, color, titulo, ejeY, moneda } = o;
  const W = 820, H = 300, dpr = 2;
  const cv = c.createCanvas(W * dpr, H * dpr);
  const ctx = cv.getContext('2d');
  ctx.scale(dpr, dpr);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, W, H);

  // Título
  ctx.fillStyle = '#0F2C55';
  ctx.font = 'bold 16px CeibalChartBold';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'alphabetic';
  ctx.fillText(titulo, 16, 28);

  const padL = 70, padR = 22, padT = 46, padB = 48;
  const plotW = W - padL - padR, plotH = H - padT - padB;
  const x0 = padL, y0 = padT, y1 = padT + plotH;

  const max = Math.max(1, ...datos.map((d: any) => Number(d[campo]) || 0));
  const marcas = marcasEje(max, 4, !moneda);
  const tope = marcas[marcas.length - 1] || 1;

  // Líneas guía + etiquetas del eje Y (TODAS las cantidades)
  ctx.strokeStyle = '#E7EDF4';
  ctx.lineWidth = 1;
  ctx.font = '12px CeibalChart';
  ctx.fillStyle = '#8894A6';
  marcas.forEach((t) => {
    const yy = y1 - (t / tope) * plotH;
    ctx.beginPath();
    ctx.moveTo(x0, yy);
    ctx.lineTo(x0 + plotW, yy);
    ctx.stroke();
    const etq = moneda ? 'Q' + t.toLocaleString('en-US') : String(t);
    ctx.textAlign = 'right';
    ctx.textBaseline = 'middle';
    ctx.fillText(etq, x0 - 8, yy);
  });

  // Ejes
  ctx.strokeStyle = '#C9D4E0';
  ctx.beginPath();
  ctx.moveTo(x0, y0);
  ctx.lineTo(x0, y1);
  ctx.lineTo(x0 + plotW, y1);
  ctx.stroke();

  // Barras
  const n = datos.length;
  const gap = n > 20 ? 2 : 4;
  const bw = Math.max(2, (plotW - gap * n) / n);
  ctx.fillStyle = color;
  datos.forEach((d: any, i: number) => {
    const v = Number(d[campo]) || 0;
    if (v <= 0) return;
    const bh = (v / tope) * plotH;
    const bx = x0 + gap / 2 + i * (bw + gap);
    barra(ctx, bx, y1 - bh, bw, bh);
  });

  // Etiquetas del eje X (día del mes)
  ctx.fillStyle = '#8894A6';
  ctx.font = '11px CeibalChart';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'alphabetic';
  const paso = Math.max(1, Math.ceil(n / 14));
  datos.forEach((d, i) => {
    if (i % paso === 0 || i === n - 1) {
      const bx = x0 + gap / 2 + i * (bw + gap) + bw / 2;
      ctx.fillText(String(d.dia), bx, y1 + 16);
    }
  });

  // Títulos de los ejes
  ctx.fillStyle = '#5A6B80';
  ctx.font = '12px CeibalChart';
  ctx.textAlign = 'center';
  ctx.fillText('Día del mes', x0 + plotW / 2, H - 12);
  ctx.save();
  ctx.translate(18, y0 + plotH / 2);
  ctx.rotate(-Math.PI / 2);
  ctx.fillText(ejeY, 0, 0);
  ctx.restore();

  return cv.toBuffer('image/png');
}

// Genera las 3 imágenes (costo, emergencias, reparaciones). Devuelve null si
// no se pueden generar, para que el reporte use su respaldo.
export function generarImagenesGraficas(
  series: DiaSerie[],
): { costo: Buffer; emergencias: Buffer; reparaciones: Buffer } | null {
  const c = obtenerCanvas();
  if (!c || !series || series.length === 0) return null;
  try {
    return {
      costo: graficaBarras(c, { datos: series, campo: 'costo', color: '#1B4B8A', titulo: 'Costo por día', ejeY: 'Costo (Q)', moneda: true }),
      emergencias: graficaBarras(c, { datos: series, campo: 'emergencias', color: '#C0392B', titulo: 'Llamadas de emergencia por día', ejeY: 'N.º de llamadas' }),
      reparaciones: graficaBarras(c, { datos: series, campo: 'reparaciones', color: '#B7791F', titulo: 'Reparaciones por día', ejeY: 'N.º de reparaciones' }),
    };
  } catch {
    return null;
  }
}
